// Dynamic sitemap.xml for NewsSparkle.
//
// URL: https://<project-ref>.supabase.co/functions/v1/sitemap
// (public/sitemap.xml — generated by scripts/sync-seo-endpoints.mjs — points
// here. The old version of that file pointed at the front-end domain, where
// this function does not exist.)

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { escapeXml, xml } from "../_shared/http.ts";
import { CATEGORY_SLUGS, STATIC_PAGES, AUTHOR_SLUGS, siteUrl } from "../_shared/site.ts";

Deno.serve(async () => {
  const base = siteUrl();
  const supabase = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_ANON_KEY")!);

  const [{ data: posts }, { data: categories }] = await Promise.all([
    supabase
      .from("posts")
      .select("slug,updated_at,published_at,keywords")
      .eq("status", "published")
      .order("published_at", { ascending: false })
      .limit(2000),
    supabase.from("categories").select("slug").limit(50),
  ]);

  const rows = (posts ?? []) as Array<{ slug: string; updated_at: string | null; published_at: string; keywords: string[] | null }>;

  // Only advertise category pages that the front end can actually render.
  const dbCategories = ((categories ?? []) as Array<{ slug: string }>).map((c) => c.slug);
  const categorySlugs = [...new Set([...CATEGORY_SLUGS, ...dbCategories])];

  const tags = new Set<string>();
  for (const post of rows) {
    for (const keyword of post.keywords ?? []) {
      const normalized = keyword?.trim().toLowerCase();
      if (normalized) tags.add(normalized);
    }
  }

  const url = (loc: string, opts: { lastmod?: string; changefreq?: string; priority?: string } = {}) => {
    const parts = [`<loc>${escapeXml(`${base}${loc}`)}</loc>`];
    if (opts.lastmod) parts.push(`<lastmod>${new Date(opts.lastmod).toISOString()}</lastmod>`);
    if (opts.changefreq) parts.push(`<changefreq>${opts.changefreq}</changefreq>`);
    if (opts.priority) parts.push(`<priority>${opts.priority}</priority>`);
    return `<url>${parts.join("")}</url>`;
  };

  const urls = [
    url("/", { changefreq: "hourly", priority: "1.0" }),
    ...STATIC_PAGES.map((p) => url(`/${p}`, { changefreq: "weekly", priority: "0.7" })),
    ...categorySlugs.map((slug) => url(`/category/${slug}`, { changefreq: "hourly", priority: "0.8" })),
    ...AUTHOR_SLUGS.map((slug) => url(`/author/${slug}`, { changefreq: "weekly", priority: "0.6" })),
    ...[...tags].slice(0, 500).map((tag) => url(`/tag/${encodeURIComponent(tag)}`, { changefreq: "daily", priority: "0.5" })),
    ...rows.map((post) =>
      url(`/post/${post.slug}`, {
        lastmod: post.updated_at || post.published_at,
        changefreq: "weekly",
        priority: "0.8",
      }),
    ),
  ].join("");

  return xml(
    `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${urls}</urlset>`,
    900,
  );
});
